// Practice questions generated by an AI model from the student's own slides.
// Works with Claude, Gemini or DeepSeek; plain fetch instead of SDKs, since the project has no dependencies.
import { HttpError } from './validate.js';
import { kindOf, pptxSlides, docxText } from './slides.js';

export const MODEL = 'claude-opus-5-5';
export const PROVIDERS = {
  claude: { model: MODEL, label: 'Claude' },
  // A busy Gemini model answers 503 "high demand" or does not answer at all; then the next one is tried.
  // gemini-3.8-flash was often overloaded in Nov 2026, so the default is the one that answered reliably.
  gemini: { model: 'gemini-3-flash-preview', label: 'Gemini', fallbacks: ['gemini-3.8-flash'], attemptTimeout: 150_000 },
  deepseek: { model: 'deepseek-flash', label: 'DeepSeek' },
};
// How many questions one run writes: the student picks the number.
export const COUNT = { min: 1, max: 30, default: 10 };
const MAX_REQUEST = 24 * 1024 * 1024; // the API takes up to 32 MB per request
const TIMEOUT = 5 * 60_000;

const SYSTEM = `You write practice questions for a university student who is preparing for an exam.
They are built only from the student's own lecture materials, which follow as numbered materials.

Rules:
- Write exactly as many multiple-choice questions as the student asks for. Spread them over the main topics the materials teach, roughly in proportion to how much the materials say about each. Use only what the materials teach.
- Give every question a short topic name (topic), 1-4 words like a chapter title, the same name for every question on that topic. If the student already has topics, reuse those exact names when a question fits one of them.
- Every question is practical: the student has to apply an idea to a new case, such as new numbers to work out, a short scenario, code or a situation to predict, or the right method to pick for a problem. No questions that only ask to recall a definition or a sentence from the slides.
- Never copy a question, an exercise or a worked example from the materials, and never reproduce questions from a quiz, test or past exam found in them. Change the setting and the values so the question cannot be used to answer a graded Moodle quiz.
- 3-5 answer options, exactly one correct. Wrong options should be mistakes a student really makes. answer_index is the 0-based index of the correct option.
- For each question give the material it comes from (material_id), the slide or page it is based on (slide, counted from 1; use 0 when the material has no slides or pages) and a short quote of up to 20 words from that slide showing the idea being tested (quote).
- For every question write a short explanation (explanation), 1-3 sentences: why the right answer is right and which slip leads to the most tempting wrong option. The student sees it after a wrong answer.
- Write in the language of the materials.
- Do not repeat questions the student already has; they are listed under their topics.`;

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['questions'],
  properties: {
    questions: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['topic', 'prompt', 'options', 'answer_index', 'explanation', 'material_id', 'slide', 'quote'],
        properties: {
          topic: { type: 'string' },
          prompt: { type: 'string' },
          options: { type: 'array', items: { type: 'string' } },
          answer_index: { type: 'integer' },
          explanation: { type: 'string' },
          material_id: { type: 'integer' },
          slide: { type: 'integer' },
          quote: { type: 'string' },
        },
      },
    },
  },
};

// materials: [{ id, filename, data: Buffer }] → content blocks for the request, how many slides each has, and what was skipped.
export function materialBlocks(materials) {
  const blocks = [];
  const slideCount = new Map();
  const skipped = [];
  let size = 0;
  for (const m of materials) {
    const kind = kindOf(m.filename);
    const label = `Material ${m.id}: ${m.filename}`;
    let added;
    try {
      if (kind === 'pdf') {
        added = [
          { type: 'text', text: `${label} (PDF; slide = page number)` },
          { type: 'document', title: m.filename, source: { type: 'base64', media_type: 'application/pdf', data: Buffer.from(m.data).toString('base64') } },
        ];
        slideCount.set(m.id, Infinity);
      } else if (kind === 'pptx') {
        const slides = pptxSlides(Buffer.from(m.data));
        if (!slides.some((s) => s.text)) throw new Error('no text on the slides');
        added = [{ type: 'text', text: `${label}\n${slides.map((s) => `--- slide ${s.slide} ---\n${s.text}`).join('\n')}` }];
        slideCount.set(m.id, Math.max(...slides.map((s) => s.slide)));
      } else if (kind === 'docx' || kind === 'text') {
        const body = kind === 'docx' ? docxText(Buffer.from(m.data)) : Buffer.from(m.data).toString('utf8');
        if (!body.trim()) throw new Error('the file has no text');
        added = [{ type: 'text', text: `${label} (no slides; slide = 0)\n${body}` }];
        slideCount.set(m.id, 0);
      } else {
        skipped.push({ filename: m.filename, reason: 'читаються лише файли PDF, PPTX, DOCX, TXT і MD' });
        continue;
      }
    } catch (err) {
      skipped.push({ filename: m.filename, reason: `не вдалося прочитати (${err.message})` });
      continue;
    }
    const addedSize = added.reduce((n, b) => n + (b.text?.length || 0) + (b.source?.data.length || 0), 0);
    if (size + addedSize > MAX_REQUEST) {
      skipped.push({ filename: m.filename, reason: 'разом з іншими файлами це більше, ніж модель прочитає за раз' });
      slideCount.delete(m.id);
      continue;
    }
    size += addedSize;
    blocks.push(...added);
  }
  return { blocks, slideCount, skipped };
}

// Keeps only well-formed questions that point at a real file and slide, at most `count` of them.
export function cleanQuestions(raw, count, slideCount) {
  const result = [];
  for (const q of Array.isArray(raw) ? raw : []) {
    if (result.length >= count) break;
    if (!q || !slideCount.has(q.material_id)) continue;
    const topic = typeof q.topic === 'string' ? q.topic.trim().replace(/\s+/g, ' ').slice(0, 120) : '';
    if (!topic) continue;
    const prompt = typeof q.prompt === 'string' ? q.prompt.trim() : '';
    const options = Array.isArray(q.options) ? q.options.map((o) => (typeof o === 'string' ? o.trim() : '')) : [];
    if (!prompt || prompt.length > 1000) continue;
    if (options.length < 2 || options.length > 6 || options.some((o) => !o || o.length > 300)) continue;
    if (new Set(options).size !== options.length) continue;
    if (!Number.isInteger(q.answer_index) || q.answer_index < 0 || q.answer_index >= options.length) continue;
    // A file without slides (DOCX, TXT, MD) has no slide numbers to point at, even if its headings say "Slide 2".
    const slide = Number.isInteger(q.slide) && slideCount.get(q.material_id) !== 0 ? q.slide : 0;
    if (slide < 0 || slide > slideCount.get(q.material_id)) continue;
    const quote = typeof q.quote === 'string' ? q.quote.trim().slice(0, 300) : '';
    const explanation = typeof q.explanation === 'string' ? q.explanation.trim().slice(0, 1000) : '';
    result.push({ topic, prompt, options, answerIndex: q.answer_index, explanation, materialId: q.material_id, slide, quote });
  }
  return result;
}

// AI_PROVIDER (claude | gemini | deepseek), AI_API_KEY, optional AI_MODEL. Without AI_PROVIDER the key's
// shape decides: "sk-ant-…" is Claude, "AIza…" or "AQ.…" is Gemini, any other key is DeepSeek. ANTHROPIC_API_KEY still works.
export function aiConfigFromEnv(env) {
  const apiKey = env.AI_API_KEY || env.ANTHROPIC_API_KEY || '';
  let provider = (env.AI_PROVIDER || '').toLowerCase();
  if (!provider) {
    if (!env.AI_API_KEY || apiKey.startsWith('sk-ant-')) provider = 'claude';
    else provider = /^(AIza|AQ\.)/.test(apiKey) ? 'gemini' : 'deepseek';
  }
  if (!PROVIDERS[provider]) throw new Error(`AI_PROVIDER must be one of: ${Object.keys(PROVIDERS).join(', ')}`);
  return { provider, apiKey, model: env.AI_MODEL || undefined };
}

const JSON_EXAMPLE = '{"questions":[{"topic":"Big O notation","prompt":"…","options":["…","…","…"],"answer_index":0,"explanation":"…",'
  + '"material_id":1,"slide":3,"quote":"…"}]}';

// Writing a question set vs. explaining one existing question: what each request asks for and gets back.
const QUESTIONS_SPEC = { system: SYSTEM, schema: SCHEMA, example: JSON_EXAMPLE };
const EXPLAIN_SPEC = {
  system: `You explain one practice exam question to a university student who just answered it wrong.
In 2-4 sentences: why the correct answer is right, worked out on the question's own numbers or case, and the slip that leads to the tempting wrong options.
Write in the language of the question. No greeting, no restating the question.`,
  schema: { type: 'object', additionalProperties: false, required: ['explanation'], properties: { explanation: { type: 'string' } } },
  example: '{"explanation":"…"}',
};

export function createAi({ provider = 'claude', apiKey, model, fetchImpl = globalThis.fetch } = {}) {
  model ||= PROVIDERS[provider].model;
  const label = PROVIDERS[provider].label;

  // busyOk: return null instead of failing when the model is busy or too slow, so the caller can try another.
  async function post(url, headers, body, { busyOk = false, timeout = TIMEOUT } = {}) {
    let res;
    try {
      res = await fetchImpl(url, {
        method: 'POST', headers: { 'content-type': 'application/json', ...headers }, body: JSON.stringify(body),
        signal: AbortSignal.timeout(timeout),
      });
    } catch (err) {
      if (err.name !== 'TimeoutError' && err.name !== 'AbortError') {
        console.error(`${label} API unreachable:`, err.message);
        throw new HttpError(502, `Не вдалося зв’язатися з ${label}. Спробуйте пізніше.`);
      }
      console.error(`${label} ${body.model} did not answer in ${timeout / 1000} s`);
      if (busyOk) return null;
      throw new HttpError(504, `${label} відповідає надто довго. Спробуйте ще раз або попросіть менше питань.`);
    }
    const data = await res.json().catch(() => null);
    if (busyOk && [429, 503].includes(res.status)) return null;
    if (!res.ok) {
      console.error(`${label} API ${res.status}:`, data?.error?.message || JSON.stringify(data?.error || data)?.slice(0, 300) || 'no details');
      if ([429, 503, 529].includes(res.status)) throw new HttpError(503, `${label} зараз перевантажений. Спробуйте за хвилину.`);
      throw new HttpError(502, 'Зараз не вдалося згенерувати питання. Спробуйте пізніше.');
    }
    return data;
  }
  const declined = () => new HttpError(422, `${label} відмовився писати питання з цих матеріалів.`);
  const cutOff = () => new HttpError(502, 'Відповідь обірвалася. Попросіть менше питань за раз.');

  // Each returns the model's JSON text. blocks are the Claude-format blocks from materialBlocks.
  const ask = {
    async claude(blocks, task, spec = QUESTIONS_SPEC) {
      const data = await post('https://api.anthropic.com/v1/messages', {
        'x-api-key': apiKey,
        'anthropic-version': '2026-10-21',
        // If a safety check declines the request, the API retries it on a fallback model by itself.
        'anthropic-beta': 'server-side-fallback-2026-07-01',
      }, {
        model,
        max_tokens: 16000,
        fallbacks: 'default',
        output_config: { effort: 'medium', format: { type: 'json_schema', schema: spec.schema } },
        system: spec.system,
        messages: [{ role: 'user', content: [...blocks, { type: 'text', text: task }] }],
      });
      if (data.stop_reason === 'refusal') throw declined();
      if (data.stop_reason === 'max_tokens') throw cutOff();
      return data.content.filter((b) => b.type === 'text').map((b) => b.text).join('');
    },

    // Gemini Interactions API.
    async gemini(blocks, task, spec = QUESTIONS_SPEC) {
      const input = blocks.map((b) => (b.type === 'document'
        ? { type: 'document', data: b.source.data, mime_type: 'application/pdf' }
        : { type: 'text', text: b.text }));
      const models = [model, ...PROVIDERS.gemini.fallbacks.filter((m) => m !== model)];
      let data = null;
      for (const [i, m] of models.entries()) {
        data = await post('https://generativelanguage.googleapis.com/v1beta/interactions', {
          'x-goog-api-key': apiKey,
          'Api-Revision': '2026-05-20',
        }, {
          model: m,
          system_instruction: spec.system,
          input: [...input, { type: 'text', text: task }],
          response_format: { type: 'text', mime_type: 'application/json', schema: spec.schema },
          generation_config: { max_output_tokens: 16000 },
          store: false,
        }, { busyOk: i < models.length - 1, timeout: PROVIDERS.gemini.attemptTimeout });
        if (data) break;
        console.error(`Gemini ${m} is busy, trying ${models[i + 1]}`);
      }
      if (data.status === 'incomplete') throw cutOff();
      if (data.status !== 'completed') throw declined();
      return (data.steps || []).filter((st) => st.type === 'model_output')
        .flatMap((st) => st.content || []).filter((c) => c.type === 'text').map((c) => c.text).join('');
    },

    // DeepSeek chat completions. PDFs go through its Files API (it parses them); JSON mode has no schema, so the prompt shows one.
    async deepseek(blocks, task, spec = QUESTIONS_SPEC) {
      const content = [];
      for (const b of blocks) {
        if (b.type !== 'document') { content.push({ type: 'text', text: b.text }); continue; }
        const form = new FormData();
        form.append('purpose', 'text_recognition');
        form.append('file', new Blob([Buffer.from(b.source.data, 'base64')], { type: 'application/pdf' }), b.title);
        const res = await fetchImpl('https://api.deepseek.com/files', {
          method: 'POST', headers: { authorization: `Bearer ${apiKey}` }, body: form, signal: AbortSignal.timeout(TIMEOUT),
        });
        const file = await res.json().catch(() => null);
        if (!res.ok || !(file?.id || file?.file_id)) {
          console.error(`DeepSeek file upload ${res.status}:`, JSON.stringify(file)?.slice(0, 300));
          throw new HttpError(502, `DeepSeek не зміг прочитати ${b.title}. Спробуйте пізніше або завантажте файл як PPTX.`);
        }
        content.push({ type: 'file', file_id: file.id || file.file_id });
      }
      content.push({ type: 'text', text: task });
      const data = await post('https://api.deepseek.com/chat/completions', { authorization: `Bearer ${apiKey}` }, {
        model,
        max_tokens: 16000,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: `${spec.system}\n\nReply with json only, in exactly this shape: ${spec.example}` },
          { role: 'user', content },
        ],
      });
      const choice = data.choices?.[0];
      if (choice?.finish_reason === 'length') throw cutOff();
      if (choice?.finish_reason === 'content_filter') throw declined();
      return choice?.message?.content || '';
    },
  };

  // count: how many questions; topics: the exam's topics so far, [{ name, existing: [prompt] }]; materials: [{ id, filename, data }]
  // examTheme: what the exam covers in the student's words (may be empty).
  async function generateQuestions({ examTitle, examTheme = '', count = COUNT.default, topics = [], materials }) {
    if (!apiKey) throw new HttpError(503, 'AI-питання на цьому сервері не налаштовані (немає AI_API_KEY)');
    const { blocks, slideCount, skipped } = materialBlocks(materials);
    if (!blocks.length) throw new HttpError(400, 'Жоден із завантажених файлів не читається. Завантажте слайди як PDF або PPTX.');
    const topicList = topics.map((t) => [
      `- ${t.name}`,
      ...t.existing.map((p) => `    already has: ${p.slice(0, 200).replace(/\s+/g, ' ')}`),
    ].join('\n')).join('\n');
    const theme = examTheme.trim()
      ? `The student says the exam covers: ${examTheme.trim()}\nKeep the questions to this; skip material outside it.\n\n`
      : '';
    const task = `Exam: ${examTitle}\n\n${theme}Write ${count} questions.\n\n`
      + (topicList ? `The student's topics so far:\n${topicList}` : 'The student has no topics yet: name them from the materials.');

    const text = await ask[provider](blocks, task);
    let parsed;
    try {
      parsed = JSON.parse(text);
    } catch {
      throw new HttpError(502, `${label} повернув щось, що не схоже на список питань. Спробуйте ще раз.`);
    }
    return { questions: cleanQuestions(parsed?.questions, count, slideCount), skipped };
  }

  // A short explanation for a question that has none (written by hand, or made before explanations existed).
  async function explainQuestion({ prompt, options, answerIndex, quote = '' }) {
    if (!apiKey) throw new HttpError(503, 'AI-питання на цьому сервері не налаштовані (немає AI_API_KEY)');
    const letters = 'ABCDEF';
    const task = [
      `Question: ${prompt}`,
      ...options.map((o, i) => `${letters[i]}) ${o}`),
      `Correct answer: ${letters[answerIndex]}) ${options[answerIndex]}`,
      quote ? `From the lecture slide: "${quote}"` : '',
    ].filter(Boolean).join('\n');
    const text = await ask[provider]([], task, EXPLAIN_SPEC);
    let explanation = '';
    try {
      explanation = String(JSON.parse(text)?.explanation || '').trim().slice(0, 1000);
    } catch { /* handled below */ }
    if (!explanation) throw new HttpError(502, `${label} не зміг пояснити це питання. Спробуйте ще раз.`);
    return explanation;
  }

  return { enabled: Boolean(apiKey), provider, model, label, generateQuestions, explainQuestion };
}
